uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;
uniform float u_color_base;
uniform float u_color_pulse;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

float distLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Evaluates the geometric distance to the nearest line to keep it razor sharp
void evaluateConnection(vec2 f, vec2 p1, vec2 offs, vec2 dir, vec2 id, float t, float connRadius, inout float minDistLine, inout float activePulse) {
    vec2 offs2 = offs + dir;
    vec2 p2 = offs2 + 0.5 + 0.4 * sin(t * 1.5 + hash22(id + offs2) * 6.28);
    float dConn = distance(p1, p2);

    if(dConn < connRadius) {
        float dLine = distLine(f, p1, p2);

        // If this line is the closest one to our pixel, store its data
        if (dLine < minDistLine) {
            minDistLine = dLine;

            // Calculate the traveling data pulse
            float pulseTime = t * 10.0 + hash21(id + offs) * 20.0;
            float pulse = smoothstep(0.8, 1.0, sin(dConn * 6.0 - pulseTime));

            // Fade pulse near the ends so it doesn't pop
            pulse *= smoothstep(connRadius, connRadius * 0.7, dConn);
            activePulse = pulse;
        }
    }
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // Interactive Mouse Parallax
    vec2 mouseOffset = (iMouse.z > 0.0) ? (iMouse.xy / iResolution.xy - 0.5) : vec2(0.0);

    // 2. Timing & Parameters
    float spd = (u_speed <= 0.0) ? 0.2 : u_speed;
    float t = iTime * spd;

    // Smooth geometric breathing
    float breathe = 1.0 + 0.05 * sin(t); 

    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale;
    float layerCount = (u_layers <= 0.0) ? 5.0 : u_layers;
    float density = (u_density <= 0.0) ? 1.0 : u_density * 2.0; 
    float connRadius = ((u_connection_radius <= 0.0) ? 1.5 : u_connection_radius * 2.5) * breathe;
    float pulseInt = (u_pulse_intensity <= 0.0) ? 1.5 : u_pulse_intensity * 3.0;

    // Colors
    float hueBase = fract(0.55 + u_color_base + (t * u_color_cycle * 0.1));
    float huePulse = fract(0.10 + u_color_pulse + (t * u_color_cycle * 0.1));

    vec3 baseCol = hsv2rgb(vec3(hueBase, 0.7, 1.0)); // Slightly less saturated for corporate/clean look
    vec3 pulseCol = hsv2rgb(vec3(huePulse, 0.8, 1.0));

    // --- Clean Gradient Background ---
    vec3 bgCenter = baseCol * 0.15; 
    vec3 bgEdge = vec3(0.02, 0.03, 0.05);
    vec3 finalColor = mix(bgCenter, bgEdge, length(uv0) * 1.2);

    // 3. Layer Loop for Crisp Alpha Depth
    for(int i = 0; i < 5; i++) {
        float fi = float(i);
        if(fi >= layerCount) break;

        // Depth
        float z = fract(fi * 0.2 + t * 0.1); 

        // Pure Alpha Fade based on depth (creates the smooth Z-depth layering)
        float fade = smoothstep(0.0, 0.2, z) * smoothstep(1.0, 0.7, z);

        float size = mix(12.0, 0.5, z) * scaleBase * density;
        vec2 layerUV = (uv + mouseOffset * (1.0 - z) * 0.5) * size;
        layerUV *= rot(z * 0.2 + fi);

        vec2 id = floor(layerUV);
        vec2 f = fract(layerUV);

        // Distance trackers for the geometric shapes
        float minDistNode = 100.0;
        float minDistLine = 100.0;
        float activePulse = 0.0;

        // Loop through neighborhood to find geometric distances
        for(int y = -1; y <= 1; y++) {
            for(int x = -1; x <= 1; x++) {
                vec2 offs = vec2(float(x), float(y));
                vec2 p1 = offs + 0.5 + 0.4 * sin(t * 1.5 + hash22(id + offs) * 6.28);

                // Track closest node
                minDistNode = min(minDistNode, length(f - p1));

                // Track closest line
                evaluateConnection(f, p1, offs, vec2(1.0, 0.0), id, t, connRadius, minDistLine, activePulse);
                evaluateConnection(f, p1, offs, vec2(0.0, 1.0), id, t, connRadius, minDistLine, activePulse);
                evaluateConnection(f, p1, offs, vec2(1.0, 1.0), id, t, connRadius, minDistLine, activePulse);
                evaluateConnection(f, p1, offs, vec2(-1.0, 1.0), id, t, connRadius, minDistLine, activePulse);
            }
        }

        // --- Crisp SDF Rendering ---
        float px = 0.015; // Anti-aliasing fringe (keeps edges smooth but sharp)

        // Draw crisp lines
        float lineThickness = 0.01;
        float lineShape = smoothstep(lineThickness + px, lineThickness, minDistLine);

        // Draw crisp "Atom" nodes (A ring with a solid core)
        float nodeRadius = 0.06;
        float nodeRing = smoothstep(nodeRadius + px, nodeRadius, minDistNode) - smoothstep(nodeRadius*0.6 + px, nodeRadius*0.6, minDistNode);
        float nodeCore = smoothstep(nodeRadius*0.3 + px, nodeRadius*0.3, minDistNode);
        float nodeShape = clamp(nodeRing + nodeCore, 0.0, 1.0);

        // --- Layer Compositing (Alpha Blending, NO BLOOM) ---
        vec4 layerData = vec4(0.0);

        // 1. Color the lines
        vec3 lineColor = mix(baseCol, pulseCol, activePulse * pulseInt);
        layerData.rgb = lineColor;
        layerData.a = lineShape;

        // 2. Color the nodes (Draw them OVER the lines)
        layerData.rgb = mix(layerData.rgb, vec3(1.0), nodeShape); // Pure white UI nodes
        layerData.a = max(layerData.a, nodeShape);

        // 3. Apply Alpha Depth
        layerData.a *= fade * 0.85; // 0.85 max opacity for a glassy look

        // Blend Layer onto the final image
        finalColor = mix(finalColor, layerData.rgb, layerData.a);
    }

    // 4. Subtle UI Vignette
    float vig = 1.0 - length(uv0) * 0.5;
    finalColor *= smoothstep(0.1, 1.0, vig);

    fragColor = vec4(finalColor, 1.0);
}
